mapper.select:
/* 관찰 항목 목록 조회 */ SELECT A.OBSRV_ARTCL_SN , A.OBSRV_ARTCL_NM , A.OBSRV_REGN_CD , C.COM_CD_NM AS OBSRV_REGN_CD_NM , A.OBSRV_REGN_DTL_NM , A.OBSRV_STTS_CD , A.OBSRV_END_YMD FROM OBSRV_ARTCL A LEFT JOIN COM_CD C ON C.COM_CD = A.OBSRV_REGN_CD WHERE A.PET_SN = #{cond.petSn} AND A.DEL_YN = 'N'
AND A.OBSRV_STTS_CD = #{cond.obsrvSttsCd}
ORDER BY A.OBSRV_ARTCL_SN

/* 관찰 회차 목록 조회(관찰일 오름차순) */ SELECT T.OBSRV_CYCL_SN , T.OBSRV_ARTCL_SN , T.CYCL_NO , T.OBSRV_DT , T.OBSRV_SZ , T.OBSRV_CHG_CD , C.COM_CD_NM AS OBSRV_CHG_CD_NM , T.MEMO_CN FROM ( SELECT Y.OBSRV_CYCL_SN , Y.OBSRV_ARTCL_SN , ROW_NUMBER() OVER (PARTITION BY Y.OBSRV_ARTCL_SN ORDER BY Y.OBSRV_DT, Y.OBSRV_CYCL_SN) AS CYCL_NO , Y.OBSRV_DT , Y.OBSRV_SZ , Y.OBSRV_CHG_CD , Y.MEMO_CN FROM OBSRV_CYCL Y JOIN OBSRV_ARTCL A ON A.OBSRV_ARTCL_SN = Y.OBSRV_ARTCL_SN WHERE A.PET_SN = #{cond.petSn} AND A.OBSRV_ARTCL_SN = #{cond.obsrvArtclSn} AND A.DEL_YN = 'N' AND Y.DEL_YN = 'N' ) T LEFT JOIN COM_CD C ON C.COM_CD = T.OBSRV_CHG_CD
AND T.OBSRV_CYCL_SN = #{cond.obsrvCyclSn}
ORDER BY T.CYCL_NO

/* 항목의 남은 회차 수 */
SELECT COUNT(*)
  FROM OBSRV_CYCL
 WHERE OBSRV_ARTCL_SN = #{obsrvArtclSn}
   AND DEL_YN = 'N'

/* 관찰 중 항목이 있는 반려동물 번호 조회 */
SELECT DISTINCT PET_SN
  FROM OBSRV_ARTCL
 WHERE OBSRV_STTS_CD = #{obsrvSttsCd}
   AND DEL_YN = 'N'

/* 공통코드 그룹의 하위 코드 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM COM_CD C
         JOIN COM_CD G
           ON G.COM_CD_SN = C.COM_CD_PRNT_SN
        WHERE G.COM_CD = #{prntComCd}
          AND G.COM_CD_PRNT_SN IS NULL
          AND C.COM_CD = #{comCd}
          AND C.USE_YN = 'Y'
       )

mapper.insert:
/* 관찰 항목 등록 */
INSERT INTO OBSRV_ARTCL
     ( PET_SN
     , OBSRV_REGN_CD
     , OBSRV_STTS_CD
     , OBSRV_ARTCL_NM
     , OBSRV_REGN_DTL_NM
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID
     , DEL_YN )
VALUES
     ( #{petSn}
     , #{obsrvRegnCd}
     , #{obsrvSttsCd}
     , #{obsrvArtclNm}
     , #{obsrvRegnDtlNm}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId}
     , 'N' )

/* 관찰 항목 상태 이력 등록 */
INSERT INTO OBSRV_ARTCL_STTS_HSTRY
     ( OBSRV_ARTCL_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , REG_DT )
VALUES
     ( #{obsrvArtclSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , NOW() )

mapper.update:
/* 관찰 종료(상태·종료일 변경) */
UPDATE OBSRV_ARTCL
   SET OBSRV_STTS_CD = #{obsrvSttsCd}
     , OBSRV_END_YMD = CURDATE()
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE OBSRV_ARTCL_SN = #{obsrvArtclSn}
   AND DEL_YN = 'N'

/* 관찰 항목 삭제 */
UPDATE OBSRV_ARTCL
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE OBSRV_ARTCL_SN = #{obsrvArtclSn}
   AND DEL_YN = 'N'

mapper.insert:
/* 관찰 회차 등록 */
INSERT INTO OBSRV_CYCL
     ( OBSRV_ARTCL_SN
     , ATCH_FILE_SN
     , OBSRV_CHG_CD
     , OBSRV_SZ
     , MEMO_CN
     , OBSRV_DT
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{obsrvArtclSn}
     , #{atchFileSn}
     , #{obsrvChgCd}
     , #{obsrvSz}
     , #{memoCn}
     , #{obsrvDt}
     , 'N'
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 관찰 회차 수정 */
UPDATE OBSRV_CYCL
   SET ATCH_FILE_SN = #{cycle.atchFileSn}
     , OBSRV_CHG_CD = #{cycle.obsrvChgCd}
     , OBSRV_SZ     = #{cycle.obsrvSz}
     , MEMO_CN      = #{cycle.memoCn}
     , OBSRV_DT     = #{cycle.obsrvDt}
     , MDFR_ID      = #{actorId}
     , MDFCN_DT     = NOW()
 WHERE OBSRV_CYCL_SN = #{cycle.obsrvCyclSn}
   AND DEL_YN = 'N'

/* 관찰 회차 삭제 */
UPDATE OBSRV_CYCL
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE OBSRV_CYCL_SN = #{obsrvCyclSn}
   AND DEL_YN = 'N'

/* 반려동물의 관찰 회차 전체 삭제 (반려동물 삭제) */
UPDATE OBSRV_CYCL Y
  JOIN OBSRV_ARTCL A
    ON A.OBSRV_ARTCL_SN = Y.OBSRV_ARTCL_SN
   SET Y.DEL_YN   = 'Y'
     , Y.MDFR_ID  = #{actorId}
     , Y.MDFCN_DT = NOW()
 WHERE A.PET_SN = #{petSn}
   AND Y.DEL_YN = 'N'

/* 반려동물의 관찰 항목 전체 삭제 (반려동물 삭제) */
UPDATE OBSRV_ARTCL
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
